files.content:
.drawer-head{
  margin-inline-end:calc((var(--icon-sm) - var(--s-10)) / 2);
}
.drawer-head{
  margin-inline-end:calc((var(--icon-sm) - var(--s-8)) / 2);
}
.drawer-head{
  margin-inline-end:calc((var(--icon-sm) - var(--s-12)) / 2);
}
@media (pointer:coarse){
  .drawer-head{
    margin-inline-end:calc((var(--icon-sm) - var(--target-touch)) / 2);
  }
}
.drawer{
  --pad:var(--s-6);
  position:fixed;
  inset:0 0 0 auto;
  margin:0;
  padding:0;
  width:min(100%, calc(45ch + 2 * var(--pad)));
  max-width:100%;
  height:100%;
  max-height:none;
  flex-direction:column;
  overflow:hidden;
  background:var(--obsidian-800);
  color:var(--obsidian-100);
  border:0;
  border-radius:0;
  box-shadow:var(--sh-3);
  font-family:var(--font-sans);
  font-size:var(--t-body);
  transform:translateX(100%);
  transition:transform var(--d-base) var(--ease-accel), overlay var(--d-base) var(--ease-accel) allow-discrete, display var(--d-base) var(--ease-accel) allow-discrete;
}
.drawer[open]{
  display:flex;
  transform:none;
  transition-timing-function:var(--ease-decel);
}
.drawer-start{
  inset:0 auto 0 0;
  transform:translateX(-100%);
}
.drawer-wide{
  width:min(100%, calc(60ch + 2 * var(--pad)));
}
.drawer-nav{
  --pad:var(--s-4);
  width:min(100%, calc(30ch + 2 * var(--pad)));
  font-size:var(--t-lead);
}
.drawer::backdrop{
  background:transparent;
  transition:background var(--d-base) var(--ease-accel), overlay var(--d-base) var(--ease-accel) allow-discrete, display var(--d-base) var(--ease-accel) allow-discrete;
}
.drawer[open]::backdrop{
  background:var(--scrim);
  backdrop-filter:blur(var(--blur-veil));
  transition-timing-function:var(--ease-decel);
}
.drawer-head{
  flex:none;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:var(--s-4);
  padding:var(--pad) var(--pad) var(--s-4);
}
.drawer-title{
  margin:0;
  font-size:var(--t-h6);
  font-weight:700;
  line-height:var(--lh-snug);
}
.drawer-body{
  flex:1;
  min-height:0;
  overflow:auto;
  padding:0 var(--pad) var(--pad);
  display:grid;
  gap:var(--s-4);
  align-content:start;
  color:var(--obsidian-200);
  font-size:var(--t-body);
}
.drawer-body > p{
  margin:0;
}
.drawer-nav .drawer-body{
  gap:var(--s-2);
}
.drawer-label{
  margin:var(--s-4) 0 0;
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  text-transform:uppercase;
  color:var(--obsidian-300);
}
.drawer-label:first-child{
  margin-top:0;
}
.drawer-foot{
  flex:none;
  display:flex;
  justify-content:flex-end;
  flex-wrap:wrap;
  gap:var(--s-2);
  padding:var(--s-4) var(--pad);
  border-top:var(--bw-1) solid var(--obsidian-700);
}
@media (max-width:480px){
  .drawer{
    width:100%;
  }
}
@media (prefers-reduced-motion:reduce){
  .drawer, .drawer[open], .drawer-start, .drawer-start[open]{
    transition:none;
    transform:none;
  }
  .drawer::backdrop, .drawer[open]::backdrop{
    transition:none;
  }
}
